/// Build the answer to `initialize`.
///
/// The version is negotiated rather than echoed — see
/// [`crate::acp::session::negotiate_version`] for why the direction matters.
/// Always `Some` for a well-formed request: an unsupported client version is answered
/// with the agent's latest version, as initialization.mdx:96 requires.
#[must_use]
pub fn initialize_response(
    request: &InitializeRequest,
    capabilities: AgentCapabilities,
    agent_info: Option<Implementation>,
) -> Option<InitializeResponse> {
    let protocol_version = negotiate_version(request.protocol_version)?;
    Some(InitializeResponse {
        protocol_version,
        agent_capabilities: capabilities,
        auth_methods: Vec::new(),
        agent_info,
        meta: None,
    })
}

