/// one that mistyped an id need the same wire code and the same readable reason.
#[must_use]
pub fn unknown_session(session_id: &str) -> RpcError {
    RpcError::new(INVALID_PARAMS, format!("no such session: {session_id}"))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::acp::proto::METHOD_NOT_FOUND;
    use crate::acp::schema::{ClientCapabilities, ContentBlock, PROTOCOL_VERSION_V1};

    #[test]
    fn every_v1_agent_method_parses() {
        // The list is from `schema/v1/meta.json`. A method missing here is answered
        // -32601 by a server that is supposed to implement it.
        let cases: Vec<(&str, Value)> = vec![
            ("initialize", serde_json::json!({ "protocolVersion": 1 })),
            ("authenticate", serde_json::json!({ "methodId": "oauth" })),
            ("session/new", serde_json::json!({ "cwd": "/w", "mcpServers": [] })),
            (
                "session/load",
                serde_json::json!({ "sessionId": "s1", "cwd": "/w", "mcpServers": [] }),
            ),
            (
                "session/prompt",
                serde_json::json!({ "sessionId": "s1", "prompt": [{ "type": "text", "text": "hi" }] }),
            ),
            ("session/cancel", serde_json::json!({ "sessionId": "s1" })),
            ("session/list", serde_json::json!({})),
            ("session/delete", serde_json::json!({ "sessionId": "s1" })),
            ("session/resume", serde_json::json!({ "sessionId": "s1" })),
            ("session/close", serde_json::json!({ "sessionId": "s1" })),
            (
                "session/set_mode",
                serde_json::json!({ "sessionId": "s1", "modeId": "m" }),
            ),
            (
                "session/set_config_option",
                serde_json::json!({ "sessionId": "s1", "configId": "o", "value": "v" }),
            ),
            ("logout", serde_json::json!({})),
        ];
        assert_eq!(cases.len(), 13, "v1 declares 13 agent methods");
        for (method, params) in cases {
            parse_call(method, Some(&params))
                .unwrap_or_else(|e| panic!("{method} must parse: {}", e.message));
        }
    }

    #[test]
    fn only_cancel_is_a_notification() {
        // Answering a notification puts an unmatched response on the wire; failing to
        // answer a request leaves its caller waiting out a deadline.
        let cancel =
            parse_call("session/cancel", Some(&serde_json::json!({ "sessionId": "s1" }))).expect("parses");
        assert!(!cancel.expects_response());

        for (method, params) in [
            ("session/prompt", serde_json::json!({ "sessionId": "s", "prompt": [] })),
            ("session/list", serde_json::json!({})),
            ("initialize", serde_json::json!({ "protocolVersion": 1 })),
        ] {
            assert!(
                parse_call(method, Some(&params))
                    .expect("parses")
                    .expects_response(),
                "{method} is a request"
            );
        }
    }

    #[test]
    fn an_unknown_method_is_named_in_its_refusal() {
        let error = parse_call("session/teleport", None).expect_err("refused");
        assert_eq!(error.code, METHOD_NOT_FOUND);
        assert!(
            error.message.contains("session/teleport"),
            "{}",
            error.message
        );
    }

    #[test]
    fn a_missing_required_field_is_named_before_any_handler_runs() {
        // Decoded here rather than by the host, so a handler cannot act on a request
        // nobody made by forgetting to check.
        let error =
            parse_call("session/prompt", Some(&serde_json::json!({ "prompt": [] }))).expect_err("refused");
        assert_eq!(error.code, INVALID_PARAMS);

        let error = parse_call("session/set_mode", Some(&serde_json::json!({ "sessionId": "s" })))
            .expect_err("refused");
        assert!(error.message.contains("modeId"), "{}", error.message);

        // And `session/new` without its required mcpServers is malformed, not empty.
        assert!(parse_call("session/new", Some(&serde_json::json!({ "cwd": "/w" }))).is_err());
    }

    #[test]
    fn a_wrong_typed_field_is_refused_rather_than_read_as_absent() {
        // The coercion this closes: an unreadable value was treated as absent, so
        // `cwd: 42` became a load with no cwd — a request nobody made, executed as
        // though they had.
        let error = parse_call(
            "session/load",
            Some(&serde_json::json!({ "sessionId": "s1", "cwd": 42, "mcpServers": [] })),
        )
        .expect_err("refused");
        assert_eq!(error.code, INVALID_PARAMS);
        assert!(error.message.contains("cwd"), "{}", error.message);

        // Required and wrong-typed are different mistakes and read differently.
        let missing = parse_call("session/set_mode", Some(&serde_json::json!({ "sessionId": "s" })))
            .expect_err("refused");
        assert!(missing.message.contains("required"), "{}", missing.message);
        let mistyped = parse_call(
            "session/set_mode",
            Some(&serde_json::json!({ "sessionId": "s", "modeId": [] })),
        )
        .expect_err("refused");
        assert!(
            mistyped.message.contains("must be a string"),
            "{}",
            mistyped.message
        );

        // An optional array must still contain what it claims to.
        assert!(parse_call(
            "session/load",
            Some(&serde_json::json!({
                "sessionId": "s1", "cwd": "/w", "mcpServers": [],
                "additionalDirectories": [1, 2]
            })),
        )
        .is_err());
    }

    #[test]
    fn the_config_option_field_is_the_one_the_schema_names() {
        // `configId`, not `optionId`. An invented name refuses every call for a field
        // the client was never asked to send.
        parse_call(
            "session/set_config_option",
            Some(&serde_json::json!({ "sessionId": "s1", "configId": "theme", "value": "dark" })),
        )
        .expect("the schema's spelling parses");
        assert!(parse_call(
            "session/set_config_option",
            Some(&serde_json::json!({ "sessionId": "s1", "optionId": "theme", "value": "dark" })),
        )
        .is_err());
    }

    #[test]
    fn set_config_option_carries_the_chosen_value() {
        // schema/v1/schema.json SetSessionConfigOptionRequest: `value` is required.
        let call = parse_call(
            "session/set_config_option",
            Some(&serde_json::json!({ "sessionId": "s1", "configId": "verbosity", "value": "brief" })),
        )
        .expect("parses");
        let AgentCall::SetConfigOption { value, .. } = call else {
            panic!("expected set_config_option");
        };
        assert_eq!(value, serde_json::json!("brief"));
        let flag = parse_call(
            "session/set_config_option",
            Some(&serde_json::json!({ "sessionId": "s1", "configId": "web", "value": true })),
        )
        .expect("a boolean option parses");
        assert!(matches!(flag, AgentCall::SetConfigOption { value: Value::Bool(true), .. }));
        for bad in [serde_json::json!({ "sessionId": "s1", "configId": "v" }), serde_json::json!({ "sessionId": "s1", "configId": "v", "value": 3 })] {
            let err = parse_call("session/set_config_option", Some(&bad)).expect_err("refused");
            assert_eq!(err.code, INVALID_PARAMS);
        }
    }

    #[test]
    fn the_session_a_call_acts_within_is_reported() {
        // What the transport routes on, and what an authorization check reads.
        let prompt = parse_call(
            "session/prompt",
            Some(&serde_json::json!({ "sessionId": "s1", "prompt": [] })),
        )
        .expect("parses");
        assert_eq!(prompt.session_id(), Some("s1"));

        let init =
            parse_call("initialize", Some(&serde_json::json!({ "protocolVersion": 1 }))).expect("parses");
        assert_eq!(init.session_id(), None, "initialize precedes every session");
    }

    #[test]
    fn initialize_answers_at_or_below_the_client_version() {
        let request = InitializeRequest {
            protocol_version: 99,
            client_capabilities: ClientCapabilities::default(),
            client_info: None,
            meta: None,
        };
        let response = initialize_response(&request, AgentCapabilities::default(), None)
            .expect("a shared version exists");
        assert_eq!(response.protocol_version, PROTOCOL_VERSION_V1);

        // Below the floor the agent answers its latest version and lets the client
        // decide whether to disconnect (initialization.mdx:96).
        let ancient = InitializeRequest {
            protocol_version: 0,
            ..request
        };
        let answer = initialize_response(&ancient, AgentCapabilities::default(), None)
            .expect("an unsupported version is answered, not refused");
        assert_eq!(answer.protocol_version, PROTOCOL_VERSION_V1);
    }

    #[test]
    fn a_prompt_carries_its_content_blocks_decoded() {
        let call = parse_call(
            "session/prompt",
            Some(&serde_json::json!({
                "sessionId": "s1",
                "prompt": [{ "type": "text", "text": "explain this" }]
            })),
        )
        .expect("parses");
        let AgentCall::Prompt(request) = call else {
            panic!("expected a prompt");
        };
        assert_eq!(request.prompt.len(), 1);
        assert_eq!(request.prompt[0].as_text(), Some("explain this"));
        assert!(matches!(request.prompt[0], ContentBlock::Text { .. }));
    }
}
